WITH scored AS (SELECT *, MAX(monthly_fee) OVER w_recent AS last4_max_monthly_fee, AVG(monthly_fee) OVER w_recent AS last4_avg_monthly_fee, MIN(monthly_fee) OVER w_recent AS last4_min_monthly_fee, ROW_NUMBER() OVER (PARTITION BY YEAR(start_date), customer_id ORDER BY start_date DESC, id) AS row_seq FROM subscriptions WHERE plan = 'enterprise' WINDOW w_recent AS (PARTITION BY status ORDER BY start_date, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW)) SELECT s.id, s.customer_id, s.plan, s.end_date, s.monthly_fee, s.last4_max_monthly_fee, s.last4_min_monthly_fee, s.row_seq, (SELECT SUM(t2.shipping_fee) FROM orders t2 WHERE t2.customer_id = s.customer_id) AS sum_order_shipping_fee FROM scored s ORDER BY monthly_fee DESC NULLS FIRST
